import {test,expect} from '@playwright/test';
import {writeFileSync} from 'node:fs';
import {installProbes} from '../__tests__/browser/fixtures/probes';
import type {} from '../__tests__/browser/fixtures/glyph-atlas';
test('profile compatibility and snapshots',async({browser})=>{
 test.setTimeout(120000);const results=[];
 for(const backend of ['core','ecs']){
 const page=await browser.newPage();await page.addInitScript(installProbes);
 await page.goto(`/glyph-atlas.html?backend=${backend}`);await expect(page.locator('output')).toHaveText('Ready');
 await page.evaluate(()=>window.mixedRenderer.textBatching(true));await page.evaluate(()=>window.mixedRenderer.configure(1000,'grouped',false));
 const before=await page.evaluate(()=>({...window.glyphAtlasProbe(),...window.mixedRenderer.state()}));
 const frame=await page.evaluate(()=>window.mixedRenderer.measure('edit',2,1));
 const after=await page.evaluate(()=>({...window.glyphAtlasProbe(),...window.mixedRenderer.state()}));
 const result={backend,visible:frame.visible,drawcalls:frame.native.drawcalls,editedFrames:3,keyChecks:after.textBatchKeyChecks-before.textBatchKeyChecks,layoutChecks:after.textLayoutChecks-before.textLayoutChecks,geometryBuilds:after.textGeometryBuilds-before.textGeometryBuilds,orderSignals:after.orderSignals-before.orderSignals,sortInputs:after.sortInputs-before.sortInputs};results.push(result);console.log(result);
 await page.evaluate(()=>window.mixedRenderer.destroy());await page.close();
 }
 writeFileSync(process.env.ORDER_PROBE_OUTPUT??'.test-results/order-before.json',JSON.stringify(results,null,2)+'\n');
});
